func Decode(in []byte) (*Request, error) {
	r := &reader{buf: in}
	r.ws()
	v, err := r.decodeRequest()
	if err != nil {
		return nil, err
	}
	r.ws()
	if r.pos < len(r.buf) {
		return nil, r.refuse("trailing_bytes")
	}
	return v, nil
}

