func (d *OperatorDispatcher) RemoteMethodProfile(contract, method string) (string, bool) {
	if contract == "abstraction.facade/endpoint@1" && method == "Describe" {
		return "see", true
	}
	if contract == "abstraction.facade/endpoint@2" && method == "Describe" {
		return "see", true
	}
	if contract != d.ServiceContract() {
		return "local", false
	}
	switch method {
	case "Hosts":
		return "local", true
	case "AddHost":
		return "local", true
	case "RemoveHost":
		return "local", true
	case "Keys":
		return "local", true
	case "IssueKey":
		return "local", true
	case "RevokeKey":
		return "local", true
	case "Audit":
		return "local", true
	case "Requests":
		return "local", true
	case "Gateway":
		return "local", true
	case "SetGateway":
		return "local", true
	case "ProgramBudgets":
		return "local", true
	case "SetProgramBudget":
		return "local", true
	}
	return "local", false
}
