func (d *SelectionOperatorV2Dispatcher) RemoteMethodProfile(contract, method string) (string, bool) {
	if contract == "abstraction.facade/endpoint@1" && method == "Describe" {
		return "see", true
	}
	if contract == "abstraction.facade/endpoint@2" && method == "Describe" {
		return "see", true
	}
	if contract != d.ServiceContract() {
		return "local", false
	}
	switch method {
	case "ReadEffective":
		return "local", true
	case "Read":
		return "local", true
	case "Put":
		return "local", true
	case "DeletePolicy":
		return "local", true
	case "ReadAccountDefault":
		return "local", true
	case "PutAccountDefault":
		return "local", true
	case "DeleteAccountDefault":
		return "local", true
	}
	return "local", false
}
